import { z } from "zod";

/**
 * Machine-readable index of EmptyEpsilon's Lua API, generated by parsing
 * `script_reference.html` from a pinned EE install (see
 * `packages/forge-core/src/catalog/parse.ts`).
 *
 * Why this exists: root `CLAUDE.md` §0.3 forbids inventing EE API calls.
 * With 463 documented methods on the classes a content editor touches,
 * that rule only survives if it is mechanical — so EE FORGE emits Lua
 * exclusively through this catalog, and a test asserts every emitted
 * `:method(` resolves here (ADR-0034 §2).
 *
 * The catalog is a *generated artifact* pinned to one EE version.
 * Upgrading EE means re-running the generator and reading the diff.
 */

/** One parameter of a documented method. */
export const EEParamSchema = z.object({
  /** Declared Lua type, verbatim from the reference (`number`, `string`, `boolean`, a class name, `ScriptSimpleCallback`, …). */
  type: z.string(),
  name: z.string(),
  /** True when the reference shows a default (`number timeout=nil`). */
  optional: z.boolean(),
  /** True for `...` parameters (`ShipTemplate:setShields(number values...)`). */
  variadic: z.boolean(),
  /** Default expression as written in the reference, or null. */
  defaultValue: z.string().nullable(),
});
export type EEParam = z.infer<typeof EEParamSchema>;

/**
 * A method or direct member. `SpaceObject.typeName` is documented as a
 * member, not a call — it is the one non-`method` kind in EE-2024.12.08.
 */
export const EEMethodSchema = z.object({
  name: z.string(),
  kind: z.enum(["method", "member"]),
  params: z.array(EEParamSchema),
  /**
   * Declared return types. Multi-return is real in EE
   * (`SpaceObject:getPosition()` → `number x, number y`), so this is a
   * list; empty means void / undocumented.
   */
  returns: z.array(z.string()),
  doc: z.string(),
  /** First `Example:` line from the docs, when present. */
  example: z.string().nullable(),
});
export type EEMethod = z.infer<typeof EEMethodSchema>;

export const EEClassSchema = z.object({
  name: z.string(),
  description: z.string(),
  /** Parent class name — method lookup walks this chain. */
  subclassOf: z.string().nullable(),
  methods: z.array(EEMethodSchema),
});
export type EEClass = z.infer<typeof EEClassSchema>;

/**
 * The reference documents enums as prose with the valid values quoted
 * (`ESystem`, `EMissileWeapons`, `Factions`, …). The generator lifts the
 * quoted values so the editor can render a select instead of a text box.
 */
export const EEEnumSchema = z.object({
  name: z.string(),
  description: z.string(),
  values: z.array(z.string()),
});
export type EEEnum = z.infer<typeof EEEnumSchema>;

export const EECatalogSchema = z.object({
  /** EE build the catalog was generated from, e.g. `EE-2024.12.08`. */
  eeVersion: z.string().min(1),
  generatedAt: z.string(),
  /** Absolute path of the `script_reference.html` that was parsed. */
  source: z.string(),
  classes: z.record(z.string(), EEClassSchema),
  /** Top-level functions (`victory`, `globalMessage`, `setScenario`, …). */
  globals: z.array(EEMethodSchema),
  enums: z.record(z.string(), EEEnumSchema),
});
export type EECatalog = z.infer<typeof EECatalogSchema>;

/**
 * Object classes a scenario can construct and an editor can place on a
 * map. Deliberately excludes the runtime-only spawns (missiles, beam and
 * explosion effects — EE creates those during combat, they are never
 * authored) and the non-SpaceObject helper classes.
 *
 * All of them are also constructible over `/exec.lua`, which matters for
 * a future live push. That includes `Zone`, despite the reference's claim
 * that *"New Zones can't be created via the exec.lua HTTP API"* — probed
 * against a live EE-2024.12.08 on 2026-08-09 and found to work
 * (`Zone():setPoints(...):setLabel(...)` returns a valid handle whose
 * `isInside()` answers correctly). See `docs/ee-api-reference.md` §15.2.
 */
export const SPAWNABLE_CLASSES = [
  "PlayerSpaceship",
  "CpuShip",
  "SpaceStation",
  "Asteroid",
  "VisualAsteroid",
  "Planet",
  "Nebula",
  "Mine",
  "BlackHole",
  "WormHole",
  "Artifact",
  "SupplyDrop",
  "ScanProbe",
  "WarpJammer",
  "Zone",
] as const;

export type SpawnableClass = (typeof SPAWNABLE_CLASSES)[number];

/**
 * What the `/exec.lua` HTTP context genuinely cannot do, probed against a
 * live EE-2024.12.08 on 2026-08-09. Relevant to any live-push tooling:
 * objects can be spawned, but *content* must come from a loaded scenario.
 *
 * - `ShipTemplate()` returns **nil** over HTTP — the global exists, the
 *   constructor yields nothing, so templates cannot be defined this way.
 *   (`ModelData()` and `FactionInfo()` both construct normally.)
 * - `addGMFunction` raises a `ScriptSimpleCallback` conversion error,
 *   matching the reference's note about upstream issue #1807.
 * - Each `/exec.lua` request runs in a **fresh Lua state**: globals set by
 *   one request are gone by the next, so a `require`d module must be
 *   re-required inside every call that uses it.
 */
export const EXEC_LUA_LIMITS = {
  cannotConstruct: ["ShipTemplate"],
  cannotCall: ["addGMFunction"],
  statePersistsAcrossCalls: false,
} as const;

/**
 * Resolve a method through the subclass chain, mirroring how EE's Lua
 * bindings inherit. Returns null when the method does not exist on the
 * class or any ancestor — which is exactly the "invented API" case the
 * codegen must refuse to emit.
 */
export function lookupMethod(
  catalog: EECatalog,
  className: string,
  methodName: string,
): { method: EEMethod; definedOn: string } | null {
  let current: string | null = className;
  const seen = new Set<string>();
  while (current !== null && !seen.has(current)) {
    seen.add(current);
    const cls: EEClass | undefined = catalog.classes[current];
    if (cls === undefined) return null;
    const method = cls.methods.find((m) => m.name === methodName);
    if (method !== undefined) return { method, definedOn: current };
    current = cls.subclassOf;
  }
  return null;
}
